INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass regelmäßige Problemlösungstreffen nur für große Teams geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren"}, {"text": "Ja", "correct": false, "because": "Größe ist nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug nutze ich, um Probleme systematisch zu analysieren?', 3, '[{"text": "Ishikawa-Diagramm", "correct": true, "because": "Strukturiert Ursachen"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Für Zeitplanung"}, {"text": "Flussdiagramm", "correct": false, "because": "Zeigt Prozesse, nicht Ursachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen ein Problemlösungstreffen effektiv?', 5, '[{"text": "Moderierte Diskussion", "correct": true, "because": "Hält Fokus"}, {"text": "Klar definierte Ziele", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Hohe Teilnehmerzahl", "correct": false, "because": "Kann ineffizient sein"}, {"text": "Spontane Themenwahl", "correct": false, "because": "Verliert Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regelmäßige Treffen fördern kontinuierliche Verbesserung. b) Sie ersetzen formelle Audits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Audits haben anderen Fokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines effektiven Treffens?', 4, '[{"text": "Teilnehmerauswahl", "correct": false, "because": "Relevante Expertise nötig"}, {"text": "Zeitmanagement", "correct": false, "because": "Sichert Effizienz"}, {"text": "Raumdekoration", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein moderiertes Treffen immer ein Protokoll braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Nein", "correct": false, "because": "Nachvollziehbarkeit wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, Lösungsvorschläge zu priorisieren?', 4, '[{"text": "Pareto-Analyse", "correct": true, "because": "Fokussiert auf Haupteinflüsse"}, {"text": "Brainstorming", "correct": false, "because": "Sammelt Ideen, nicht priorisieren"}, {"text": "SWOT-Analyse", "correct": false, "because": "Für strategische Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Problemlösungstreffen nur für Produktionsprobleme geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für IT und Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Treffen nur für Fehlerbehebung?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Prozessoptimierung"}, {"text": "Ja", "correct": false, "because": "Umfassender Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern die Zusammenarbeit in einem Teamtreffen?', 5, '[{"text": "Offene Kommunikation", "correct": true, "because": "Fördert Ideenaustausch"}, {"text": "Klarer Moderator", "correct": true, "because": "Hält Struktur"}, {"text": "Maximale Teilnehmerzahl", "correct": false, "because": "Kann Chaos verursachen"}, {"text": "Keine Agenda", "correct": false, "because": "Fehlt Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wenn ich ein Treffen organisiere, was ist primär?', 4, '[{"text": "Klar definierte Probleme", "correct": true, "because": "Sichert relevante Diskussion"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Luxuriöse Location", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Protokoll ist Pflicht. b) Nur Führungskräfte leiten Treffen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leitung flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich bei der Problemlösung vorgehe?', 4, '[{"text": "Strukturierte Analyse mit 5-Why", "correct": true, "because": "Findet Ursachen"}, {"text": "Spontane Diskussion", "correct": false, "because": "Unstrukturiert"}, {"text": "Nur Experten befragen", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Organisation eines Treffens unwichtig?', 3, '[{"text": "Agenda", "correct": false, "because": "Sichert Struktur"}, {"text": "Teilnehmerauswahl", "correct": false, "because": "Relevante Expertise nötig"}, {"text": "Kaffeepausenlänge", "correct": true, "because": "Kein Kernfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Stimmt es, dass ich in solchen Treffen nur technische Probleme löse?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Themen"}, {"text": "Ja", "correct": false, "because": "Breiterer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, langfristige Verbesserungen zu erzielen?', 4, '[{"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Fördert Nachhaltigkeit"}, {"text": "Einmalige Lösung", "correct": false, "because": "Zu kurzfristig"}, {"text": "Hohe Standardisierung", "correct": false, "because": "Einschränkt Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Moderator strukturiert Diskussionen. b) Jeder Teilnehmer muss Experte sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Protokoll in einem Treffen?', 3, '[{"text": "Ergebnisse dokumentieren", "correct": true, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Teilnehmer motivieren", "correct": false, "because": "Kein Hauptzweck"}, {"text": "Probleme lösen", "correct": false, "because": "Diskussion löst Probleme"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Treffen ohne Vorbereitung effektiv sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vorbereitung sichert Fokus"}, {"text": "Ja", "correct": false, "because": "Fehlt Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Moderation eines Treffens?', 4, '[{"text": "Klare Zielvorgabe", "correct": true, "because": "Sichert Ergebnisorientierung"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Maximale Redezeit", "correct": false, "because": "Kann abschweifen"}]');
